      C("Gripping ↔ ___", ["boring", "moving", "acclaimed"], "boring", "Захопливий ↔ нудний.", "Захватывающий ↔ скучный."),
      C("Overrated ↔ ___", ["underrated", "acclaimed", "predictable"], "underrated", "Переоцінений ↔ недооцінений.", "Переоценённый ↔ недооценённый."),
