   B("We apologise for any inconvenience caused", "We apologise for…", tp="register"),
   T("Ухвалили рішення закрити офіс.", "Было принято решение закрыть офис.", "The decision was made to close the office.", "Decision.", acc=["A decision was made to close the office.", "The decision has been made to close the office.", "It was decided to close the office."], tp="nominalisation"),
   L("There was a dramatic increase in sales.", ["There was a dramatic increase in sales.", "There was a dramatic decrease in sales.", "There was a dramatically increase in sales."], "Increase.", tp="nominalisation"),
