      C("— Did we miss the train? — I'm afraid ___ .", ["so", "it", "yes"], "so", "I'm afraid so.", tp="ellipsis-so-not"),
      C("— Is the museum free? — I don't think ___ .", ["so", "not", "it"], "so", "I don't think so.", tp="ellipsis-so-not"),
      C("— Will he apologise? — I ___ it.", ["doubt", "hope", "think"], "doubt", "I doubt it.", tp="ellipsis-so-not"),
      C("Anyone who wishes to leave may ___ so now.", ["do", "make", "go"], "do", "Do so.", tp="ellipsis-so-not"),
      M([("I think so.", ("Думаю, так.", "Думаю, да.")), ("I hope not.", ("Сподіваюся, ні.", "Надеюсь, нет.")), ("I'm afraid so.", ("На жаль, так.", "К сожалению, да.")), ("I doubt it.", ("Сумніваюся.", "Сомневаюсь."))], "Короткі відповіді.", "Короткие ответы.", tp="ellipsis-so-not"),
      X("— Will it be cold? — I hope no.", "— Will it be cold? — I hope not.", "I hope not.", tp="ellipsis-so-not"),
