      M([("Want a lift?", "Do you want a lift?"), ("Got it.", "I've got it."), ("Sounds good.", "It sounds good."), ("Anything else?", "Is there anything else?")], "Коротко → повністю.", "Коротко → полностью.", tp="ellipsis-spoken"),
      L("Seen my keys anywhere?", ["Seen my keys anywhere?", "Seen my kids anywhere?", "Send my keys anywhere?"], "Have you seen…", tp="ellipsis-spoken"),
